func (t *TransmuterModule) resolveConflictTarget(row *masterBindingRuntime, colTypes map[string]string) string {
	pk := strings.TrimSpace(t.resolveMasterPK(row))
	if pk == "" || strings.EqualFold(pk, "_gpay_id") || strings.EqualFold(pk, "_source_id") {
		return "_gpay_id"
	}
	for col := range colTypes {
		if strings.EqualFold(col, pk) {
			return col
		}
	}
	return "_gpay_id"
}

